selector_to_html = {"a[href=\"#pyskyfire.common.physics.h_gas_bartz\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.h_gas_bartz\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">h_gas_bartz</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">D_t</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cp_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Pr_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">c_star</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_t</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sigma</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute the Bartz hot-gas correlation without curvature correction.</p></dd>", "a[href=\"#pyskyfire.common.physics.gnielinski_temperature_correction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.gnielinski_temperature_correction\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">gnielinski_temperature_correction</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">bulk_temperature</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall_temperature</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Gnielinski\u2019s wall/bulk property factor for a heated gas, <code class=\"docutils literal notranslate\"><span class=\"pre\">(T_b/T_w)^0.45</span></code>.</p><p>Multiplies a bulk-property Gnielinski Nusselt number. Toward a hot wall the\nfluid thins and its transport properties shift, which bulk properties alone\ndo not see. A cooled fluid (wall colder than bulk) takes a factor of one,\nGnielinski\u2019s exponent for gas cooling being zero. The form was fitted at\nmoderate temperature ratios; a cryogen against a hot wall lies well beyond\nthem, so treat the result there as an extrapolation.\nReference: Gnielinski (1976); VDI Heat Atlas, chapter G1.</p></dd>", "a[href=\"#pyskyfire.common.physics.h_coolant_colburn\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.h_coolant_colburn\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">h_coolant_colburn</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">k_cf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">D_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Cp_cr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu_cf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">phi_curv</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Colburn correlation for turbulent coolant-side heat transfer.</p><p class=\"rubric\">Notes</p></dd>", "a[href=\"#pyskyfire.common.physics.nusselt_gnielinski\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.nusselt_gnielinski\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">nusselt_gnielinski</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Pr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">darcy_factor</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Gnielinski turbulent internal-flow Nusselt number (Darcy convention).</p><p>Validity: 2300 &lt;= Re &lt;= 5e6, 0.5 &lt;= Pr &lt;= 2000. Values outside these\nranges raise. For transition/laminar handling use <code class=\"docutils literal notranslate\"><span class=\"pre\">h_internal</span></code>.\nReference: Gnielinski (1976);\nequation and example: <a class=\"reference external\" href=\"https://ht.readthedocs.io/en/release/ht.conv_internal.html\">https://ht.readthedocs.io/en/release/ht.conv_internal.html</a></p></dd>", "a[href=\"../../ducts/index.html#module-pyskyfire.ducts\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts<a class=\"headerlink\" href=\"#module-pyskyfire.ducts\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct hydraulics shared by cooling channels, piping and manifolds.</p><p>This subpackage contains shared path geometry, explicit pipe hydraulics,\nannular ducts, orifices and orifice plates, and volute and collector manifolds. It depends only on <a class=\"reference internal\" href=\"../../common/index.html#module-pyskyfire.common\" title=\"pyskyfire.common\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.common</span></code></a> for\nplanar section primitives and friction correlations and <a class=\"reference internal\" href=\"../../thermo/index.html#module-pyskyfire.thermo\" title=\"pyskyfire.thermo\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.thermo</span></code></a> for fluid state records,\nand it does not import from <a class=\"reference internal\" href=\"../../regen/index.html#module-pyskyfire.regen\" title=\"pyskyfire.regen\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen</span></code></a> or <a class=\"reference internal\" href=\"../../network/index.html#module-pyskyfire.network\" title=\"pyskyfire.network\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.network</span></code></a>,\nso cooling channels, turbopump hardware and engine-network adapters can all\ndepend on it without a cycle.</p>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.physics.h_gas_bartz_enthalpy_driven\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.h_gas_bartz_enthalpy_driven\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">h_gas_bartz_enthalpy_driven</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">k_gr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">D_hyd</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Cp_gr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu_gr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_chmb</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_gr</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute the hot-gas-side heat-transfer coefficient (Bartz correlation, enthalpy-based).</p><p class=\"rubric\">Notes</p><p>This form of the Bartz correlation uses the ratio <code class=\"docutils literal notranslate\"><span class=\"pre\">T_g/T_gr</span></code> to\naccount for variable-property effects between free-stream and reference conditions.</p><p>subscript g denotes free stream gas properties\nsubscript r denotes reference enthalpy conditions which are averaged between the free stream and wall metal conditions</p></dd>", "a[href=\"#pyskyfire.common.physics.f_darcy\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.f_darcy\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">f_darcy</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Composite laminar\u2013turbulent Darcy friction factor with smooth transition.</p></dd>", "a[href=\"#pyskyfire.common.physics.kader_temperature_plus\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.kader_temperature_plus\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">kader_temperature_plus</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">y_plus</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prandtl</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">eta</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return Kader\u2019s dimensionless turbulent temperature profile.</p><p class=\"rubric\">Notes</p><p>This is the smooth-wall, fully turbulent interpolation of Kader (1981),\nincluding its outer-layer correction. It blends the conductive sublayer\nand logarithmic layer without assuming a molecular Prandtl number near\nunity. Fluid properties are nevertheless treated as locally constant.</p></dd>", "a[href=\"#pyskyfire.common.physics.f_darcy_turbulent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.f_darcy_turbulent\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">f_darcy_turbulent</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Turbulent Darcy friction factor using Petukhov or Colebrook\u2013White.</p></dd>", "a[href=\"#pyskyfire.common.physics.friction_velocity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.friction_velocity\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">friction_velocity</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">velocity</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">darcy_factor</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return friction velocity from a bulk velocity and Darcy factor.</p><p>The Darcy-Weisbach convention gives\n<code class=\"docutils literal notranslate\"><span class=\"pre\">u_tau</span> <span class=\"pre\">=</span> <span class=\"pre\">abs(velocity)</span> <span class=\"pre\">*</span> <span class=\"pre\">sqrt(f_D</span> <span class=\"pre\">/</span> <span class=\"pre\">8)</span></code>.</p></dd>", "a[href=\"#pyskyfire.common.physics.ReDh_laminar\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.ReDh_laminar\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ReDh_laminar</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">2300</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.physics.h_internal\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.h_internal\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">h_internal</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Pr</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">k</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">darcy_factor</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">laminar_nusselt</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">3.66</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">bulk_temperature</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">wall_temperature</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Internal coefficient [W/m\u00b2/K], with an explicit laminar approximation.</p><p>Uses the supplied laminar Nu below Re=2300 and linearly blends to\nGnielinski at Re=4000. The default 3.66 represents a fully developed\ncircular tube at constant wall temperature. For noncircular or partially\nheated passages supply a suitable laminar_nusselt or coefficient model.\nHydraulic-diameter turbulent use in noncircular passages is an engineering\napproximation. Curvature enhancement is not added to heat transfer.</p><p>Given both <code class=\"docutils literal notranslate\"><span class=\"pre\">bulk_temperature</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">wall_temperature</span></code> [K], the\nGnielinski part is multiplied by\n<a class=\"reference internal\" href=\"#pyskyfire.common.physics.gnielinski_temperature_correction\" title=\"pyskyfire.common.physics.gnielinski_temperature_correction\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">gnielinski_temperature_correction()</span></code></a>; the laminar part is not.</p></dd>", "a[href=\"#pyskyfire.common.physics.u_coolant\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.u_coolant\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">u_coolant</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mdot_c_single_channel</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">A_cool</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute coolant velocity.</p></dd>", "a[href=\"#pyskyfire.common.physics.reynolds\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.reynolds\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">reynolds</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">L</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute the Reynolds number.</p></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.physics._curvature_group\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics._curvature_group\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_curvature_group</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_scale</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return <code class=\"docutils literal notranslate\"><span class=\"pre\">Re</span> <span class=\"pre\">*</span> <span class=\"pre\">(length_scale</span> <span class=\"pre\">/</span> <span class=\"pre\">|R|)^2</span></code> or zero if straight.</p></dd>", "a[href=\"#pyskyfire.common.physics.phi_curv_friction\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.phi_curv_friction\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">phi_curv_friction</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">D_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>RTE/Ito curvature multiplier for the Darcy friction factor.</p><p>The correlation uses hydraulic radius <code class=\"docutils literal notranslate\"><span class=\"pre\">r_h</span> <span class=\"pre\">=</span> <span class=\"pre\">D_h/4</span></code> and applies only\nfor <code class=\"docutils literal notranslate\"><span class=\"pre\">Re</span> <span class=\"pre\">*</span> <span class=\"pre\">(r_h/R)^2</span> <span class=\"pre\">&gt;</span> <span class=\"pre\">6</span></code>.  It is independent of bend direction.</p><p>This is a thin wrapper over\n<code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts.curvature_multiplier()</span></code> with <code class=\"docutils literal notranslate\"><span class=\"pre\">model='native'</span></code>. The\nphysics lives in <a class=\"reference internal\" href=\"../../ducts/index.html#module-pyskyfire.ducts\" title=\"pyskyfire.ducts\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts</span></code></a> so that piping and cooling\nchannels share one implementation.</p></dd>", "a[href=\"#pyskyfire.common.physics.T_aw\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.T_aw\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">T_aw</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">gamma</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">M_inf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_inf</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Pr</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Compute the adiabatic-wall (recovery) temperature.</p><p class=\"rubric\">Notes</p><p>The recovery factor <code class=\"docutils literal notranslate\"><span class=\"pre\">r</span></code> is approximated as <code class=\"docutils literal notranslate\"><span class=\"pre\">Pr^(1/3)</span></code>,\nvalid for turbulent flow. For laminar conditions, a smaller\nrecovery factor should be used (\u2248 Pr\u2070\u02d9\u2075).</p><p>TODO: Implement a more robust version that could also handle laminar flow, in case this function is suddenly\nused in a function where this makes sense.</p></dd>", "a[href=\"#pyskyfire.common.physics.ReDh_turbulent\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.ReDh_turbulent\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ReDh_turbulent</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">3500</span></span></dt><dd></dd>", "a[href=\"#pyskyfire.common.physics.phi_curv\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.phi_curv\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">phi_curv</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Re_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">D_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">R_curv</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>RL10 curvature factor for coolant-side Colburn heat transfer.</p><p class=\"rubric\">Notes</p><p>The RL10 model uses\n<code class=\"docutils literal notranslate\"><span class=\"pre\">[Re</span> <span class=\"pre\">*</span> <span class=\"pre\">(0.5</span> <span class=\"pre\">D_h</span> <span class=\"pre\">/</span> <span class=\"pre\">R)^2]**(+/-</span> <span class=\"pre\">0.05)</span></code>.  Its expression has no sensible\nzero-curvature limit if extrapolated below a group of one, so this\nimplementation returns one there.  That makes the straight-channel limit\nfinite and joins the correlation continuously at its neutral value.</p></dd>", "a[href=\"#pyskyfire.common.physics.sigma\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.sigma\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">sigma</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_c</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">gamma_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">M_g</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">omega</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Dimensionless property-variation factor used in Bartz correlation.</p></dd>", "a[href=\"#pyskyfire.common.physics.kader_temperature_profile\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.kader_temperature_profile\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">kader_temperature_profile</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_wall</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_edge</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">cp</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mu</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">prandtl</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u_tau</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">200</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Reconstruct one local turbulent thermal boundary layer with Kader.</p><p>The supplied heat-transfer coefficient fixes the convective wall flux as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">h</span> <span class=\"pre\">*</span> <span class=\"pre\">(T_edge</span> <span class=\"pre\">-</span> <span class=\"pre\">T_wall)</span></code>. The Kader edge condition is inverted for the\nfriction Reynolds number, so this is a local profile reconstruction, not\nan axial boundary-layer-growth calculation.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.physics.f_darcy_laminar\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics.f_darcy_laminar\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">f_darcy_laminar</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">ReDh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Dh</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Laminar Darcy friction factor.</p></dd>", "a[href=\"#pyskyfire.common.physics._resolve_roughness\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.physics._resolve_roughness\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.physics.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_resolve_roughness</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return absolute roughness [m] from regen\u2019s callable-or-<code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code> form.</p></dd>", "a[href=\"#module-pyskyfire.common.physics\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.physics<a class=\"headerlink\" href=\"#module-pyskyfire.common.physics\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
